<template><section class="tasks"><header class="head"><div><small>SEO AI WORKSPACE</small><h2>任务与告警</h2><p>把审计问题分派为可跟踪的修复任务。</p></div><el-button @click="load" :loading="loading"><i class="fas fa-refresh"/> 刷新</el-button></header><div class="toolbar"><el-select v-model="severity" clearable placeholder="全部严重度" @change="load"><el-option label="严重 / 高" value="high"/><el-option label="中" value="medium"/><el-option label="低" value="low"/></el-select><el-tag type="info">{{ rows.length }} 个待办</el-tag></div><el-table :data="rows" v-loading="loading" stripe><el-table-column label="严重度" width="100"><template #default="{row}"><el-tag :type="row.severity==='low'?'info':'danger'">{{ names[row.severity]||row.severity }}</el-tag></template></el-table-column><el-table-column prop="title" label="问题" min-width="220"/><el-table-column prop="site_name" label="站点" min-width="150"/><el-table-column prop="evidence" label="证据" min-width="280"/><el-table-column label="状态" width="140"><template #default="{row}"><el-select v-model="row.status" size="small" @change="update(row)"><el-option label="待处理" value="open"/><el-option label="处理中" value="in_progress"/><el-option label="已解决" value="resolved"/><el-option label="忽略" value="ignored"/></el-select></template></el-table-column></el-table></section></template>
<script setup>import{ref,onMounted}from'vue';import api from'@/api';import{ElMessage}from'element-plus';const rows=ref([]),loading=ref(false),severity=ref(''),names={critical:'严重',high:'高',medium:'中',low:'低'};async function load(){loading.value=true;try{const r=await api.get('/user/seo/issues',{params:{status:'open',severity:severity.value||undefined}});rows.value=r.data?.data||r.data||[]}finally{loading.value=false}}async function update(row){try{await api.put(`/user/seo/issues/${row.id}/status`,{status:row.status});ElMessage.success('任务状态已更新')}catch{ElMessage.error('更新失败');load()}}onMounted(load)</script>
<style scoped>.tasks{max-width:1180px;margin:auto}.head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.head small{color:#1677ff;font-weight:700}.head h2{font-size:24px;margin:5px 0}.head p{margin:0;color:#667085}.toolbar{display:flex;gap:12px;align-items:center;margin-bottom:14px}.toolbar .el-select{width:160px}</style>
